<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\OAuth\Gdpr\Application\Usecase\ExportUserData\ExportUserDataParams;
use Civi\Lughauth\Features\OAuth\Gdpr\Application\Usecase\ExportUserData\ExportUserDataResult;
use Civi\Lughauth\Features\OAuth\Gdpr\Application\Usecase\ExportUserData\ExportUserDataUsecase;
use Civi\Lughauth\Features\OAuth\Gdpr\Application\Usecase\DeleteUserData\DeleteUserDataParams;
use Civi\Lughauth\Features\OAuth\Gdpr\Application\Usecase\DeleteUserData\DeleteUserDataUsecase;
use Civi\Lughauth\Features\OAuth\Gdpr\Domain\GdprSubjectData;
use Civi\Lughauth\Features\OAuth\Gdpr\Domain\GdprDataPackage;
use Civi\Lughauth\Features\OAuth\Gdpr\Domain\Gateway\GdprDataExportGateway;
use Civi\Lughauth\Features\OAuth\Gdpr\Domain\Gateway\GdprDataDeleteGateway;

final class GdprUsecasesUnitTest extends TestCase
{
    // --- ExportUserDataParams ---

    public function test_export_params_stores_fields(): void
    {
        $p = new ExportUserDataParams('user-1', 'tenant-a');
        $this->assertSame('user-1', $p->subjectId);
        $this->assertSame('tenant-a', $p->tenant);
    }

    // --- ExportUserDataUsecase ---

    public function test_export_usecase_returns_result_with_package(): void
    {
        $section = new GdprSubjectData('profile', ['name' => 'Alice']);
        $gateway = new class($section) implements GdprDataExportGateway {
            public function __construct(private GdprSubjectData $section) {}
            public function exportForSubject(string $subjectId, string $tenant): array { return [$this->section]; }
        };

        $usecase = new ExportUserDataUsecase($gateway);
        $result = $usecase->export(new ExportUserDataParams('user-1', 'tenant-a'));

        $this->assertInstanceOf(ExportUserDataResult::class, $result);
        $this->assertInstanceOf(GdprDataPackage::class, $result->package);
        $this->assertSame('user-1', $result->package->subjectId);
        $this->assertSame('tenant-a', $result->package->tenant);
        $arr = $result->package->toArray();
        $this->assertArrayHasKey('profile', $arr['data']);
    }

    // --- DeleteUserDataParams ---

    public function test_delete_params_stores_fields(): void
    {
        $p = new DeleteUserDataParams('user-1', 'tenant-a');
        $this->assertSame('user-1', $p->subjectId);
        $this->assertSame('tenant-a', $p->tenant);
    }

    // --- DeleteUserDataUsecase ---

    public function test_delete_usecase_delegates_to_gateway(): void
    {
        $deleted = null;
        $gateway = new class($deleted) implements GdprDataDeleteGateway {
            public ?array $deleted = null;
            public function deleteForSubject(string $subjectId, string $tenant): void
            {
                $this->deleted = ['subject' => $subjectId, 'tenant' => $tenant];
            }
        };

        $usecase = new DeleteUserDataUsecase($gateway);
        $usecase->delete(new DeleteUserDataParams('user-1', 'tenant-a'));

        $this->assertSame(['subject' => 'user-1', 'tenant' => 'tenant-a'], $gateway->deleted);
    }
}
